#!/usr/bin/env node
/**
 * AUTO-GENERATED by GateMaster — trae 原生 hook
 * Rule: 触碰生产环境前必须先说明操作并等待确认才能执行
 * Rule Key: host-rule-4f62bd21b386
 * Rule ID: 7a3b0219-6ede-47e4-8994-977c2bc71193
 * Enforcement: must
 * Trae event: PreToolUse
 * Matcher: RunCommand
 *
 * 场景发散设计结论：
 * "触碰生产环境"包含：
 *   - kubectl apply/create/delete/replace/rollout → critical
 *   - helm install/upgrade/uninstall/rollback → critical
 *   - docker-compose up + prod/production → critical
 *   - terraform apply/destroy/import → critical
 *   - ansible-playbook + prod → critical
 *   - 数据库迁移到生产: migrate --env=prod → critical
 *   - deploy + prod/production → critical
 *   - scp/ssh 到生产服务器 → critical
 *   - npm run dev, pytest, git commit, make test → skip（本地开发）
 *   - npm run build, tsc → skip（构建命令）
 *
 * shouldRun: 命令匹配生产环境关键词且不是明确的本地命令时触发
 * run: REJECT 并要求先说明操作内容、影响范围、回滚方案，等待人工确认
 */

import { runHook } from "./_lib.mjs";

const PROD_SIGNALS = [
  /\bkubectl\b[\s\S]*\b(apply|create|delete|replace|rollout|scale|exec|edit)\b/i,
  /\bhelm\b[\s\S]*\b(install|upgrade|uninstall|rollback|delete)\b/i,
  /\bdocker-compose\b[\s\S]*\bup\b[\s\S]*\b(prod|production)\b/i,
  /\bterraform\b[\s\S]*\b(apply|destroy|import)\b/i,
  /\bansible-playbook\b[\s\S]*\b(prod|production)\b/i,
  /\bmigrate\b[\s\S]*\b(prod|production|--env=prod)\b/i,
  /\bdeploy\b[\s\S]*\b(prod|production)\b/i,
  /\bscp\b[\s\S]*\b(prod|production)\b/i,
  /\bssh\b[\s\S]*\b(prod|production)\b/i,
  /\baws\b[\s\S]*\b--profile\s+prod/i,
  /\bgcloud\b[\s\S]*\b--project=prod/i,
];

const LOCAL_COMMANDS = [
  /^npm\s+(run\s+)?(dev|test|build|lint|tsc|start)\b/i,
  /^npx\s+(jest|pytest|tsc|eslint|prettier)\b/i,
  /^pytest\b/i,
  /^make\s+(test|build|lint)\b/i,
  /^git\s+(add|commit|push|pull|status|diff|log|checkout|branch|stash)\b/i,
  /^node\s+/i,
  /^curl\s+/i,
  /^echo\s+/i,
  /^cd\s+/i,
  /^ls\s+/i,
  /^mkdir\s+/i,
  /^cp\s+/i,
  /^mv\s+/i,
  /^rm\s+/i,
];

function getCommand(context) {
  return context?.tool_input?.command
    || context?.tool_input?.cmd
    || context?.command
    || context?.cmd
    || "";
}

function shouldRun(context) {
  const command = getCommand(context);
  if (!command) return false;
  if (LOCAL_COMMANDS.some(p => p.test(command.trim()))) return false;
  return PROD_SIGNALS.some(p => p.test(command));
}

function run(context) {
  const command = getCommand(context);

  return {
    action: "REJECT",
    reason: `检测到生产环境操作: ${command.substring(0, 200)}。触碰生产环境前必须先说明操作内容和影响范围，等待人工确认后才能执行。`,
    suggestions: [
      "说明即将执行的具体操作",
      "说明影响范围（哪些服务/用户会受影响）",
      "说明回滚方案（如果操作失败如何恢复）",
      "等待用户明确回复\"确认执行\"后再重试此命令",
    ]
  };
}

runHook(shouldRun, run, "PreToolUse");
